const make=(tag,cls,text)=>{const e=document.createElement(tag);e.className=cls;if(text)e.textContent=text;return e;};
/** Captions follow the inspected object; they never capture focus or stop the world. */
export function mountFieldFeedback({getWorld,getRenderer,onSave=()=>{}}){
 const root=make('aside','field-feedback');root.hidden=true;root.setAttribute('aria-label','In-world inspection');const caption=make('p','field-caption');caption.setAttribute('role','status');caption.setAttribute('aria-live','polite');const receipts=make('div','field-receipts'),actions=make('div','field-actions');root.append(caption,receipts,actions);for(const kind of ['keydown','keyup'])root.addEventListener(kind,e=>{if(e.target.closest('button'))e.stopPropagation();});document.querySelector('#game').append(root);let current=null,until=0,pageAt=0,lastPage=0;
 function hide(){root.hidden=true;current=null;actions.replaceChildren();}
 function show(event){const w=getWorld(),renderer=getRenderer();current=event;pageAt=0;lastPage=performance.now();until=lastPage+(event.actions.length?(event.object?.bellArc?Infinity:16000):Math.min(18000,Math.max(6000,event.pages.join(' ').length*35)));root.hidden=false;actions.replaceChildren();receipts.replaceChildren();caption.textContent=event.pages[0]||'';for(const effect of event.effects){const chip=make('span','field-receipt '+effect.kind,effect.text);receipts.append(chip);if(renderer)renderer.effects.push({kind:'number',x:w.state.x,y:w.state.y-1-event.effects.indexOf(effect)*.3,value:effect.text,color:effect.kind==='spent'?'#e9ba9c':'#b5f0c9',t:0,life:2.6});}
  if(renderer&&event.xy)renderer.effects.push({kind:'inspect',x:event.xy[0]+.5,y:event.xy[1]+.5,color:event.effects.length?'#aee9c5':'#e5cf9e',t:0,life:1.1});
  for(const action of event.actions){const b=make('button','field-action',action.label);b.type='button';b.onclick=e=>{e.stopPropagation();actions.replaceChildren();if(action.action()===false){hide();return;}onSave();getRenderer()?.canvas.focus();};actions.append(b);}onSave();update(true);}
 function update(visible){if(!current)return;const w=getWorld(),r=getRenderer(),now=performance.now();if(!visible||w.state.scene!==current.scene||w.state.mode!=='field'||now>until||current.xy&&Math.hypot(w.state.x-current.xy[0]-.5,w.state.y-current.xy[1]-.5)>4){hide();return;}if(current.pages.length>1&&now-lastPage>Math.max(4500,(current.pages[pageAt]?.length||0)*35)){pageAt=(pageAt+1)%current.pages.length;caption.textContent=current.pages[pageAt];lastPage=now;}
  const tr=r?.transform;if(!tr)return;const xy=current.xy||[w.state.x,w.state.y],x=(xy[0]+.5)*48*tr.z+tr.ox,y=(xy[1]-.3)*48*tr.z+tr.oy;const width=Math.min(390,r.width-24);root.style.width=width+'px';root.style.left=Math.max(12,Math.min(r.width-width-12,x-width/2))+'px';const top=r.layout?.top||110,bottom=r.height-(r.layout?.bottom||24)-root.offsetHeight-8;root.style.top=Math.max(top,Math.min(Math.max(top,bottom),y-root.offsetHeight-18))+'px';
 }
 return{show,update,hide};
}
